package meteordevelopment.meteorclient.gui;import java.util.*;public class GuiThemes {public static final Map<String,GuiTheme> map=new LinkedHashMap<>();static GuiTheme active;public static int saves;public static void add(GuiTheme t){map.put(t.name,t);}public static void select(String name){active=map.get(name);}public static GuiTheme get(){return active;}public static void save(){saves++;}}
